using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;

namespace sv_96396acd6b364c1c8ac8645596af78b0.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that returns a hardcoded user and
/// persists the claims via PersistentComponentState so the WebAssembly client
/// can restore them after the runtime takes over.
/// </summary>
public sealed class FakeAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _persistentState;
    private readonly PersistingComponentStateSubscription _subscription;

    private static readonly AuthenticationState _authState = new(new ClaimsPrincipal(new ClaimsIdentity(
        new[]
        {
            new Claim(ClaimTypes.Name, "bob@example.com"),
            new Claim(ClaimTypes.Email, "bob@example.com"),
            new Claim(ClaimTypes.Role, "User"),
            new Claim(ClaimTypes.Role, "Editor"),
        },
        authenticationType: "Fake")));

    public FakeAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        _persistentState = persistentState;
        _subscription = _persistentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => Task.FromResult(_authState);

    private Task OnPersistingAsync()
    {
        var principal = _authState.User;
        if (principal.Identity?.IsAuthenticated == true)
        {
            var claims = principal.Claims.Select(c => new ClaimData(c.Type, c.Value)).ToList();
            _persistentState.PersistAsJson(nameof(ClaimData), claims);
        }

        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

public sealed record ClaimData(string Type, string Value);

